	["A veces el golpe ni te toca."] = "Às vezes o golpe nem encosta em você.",
	["Abajo"] = "Para baixo",
	["Abajo del modelo, elige lo que hace tu personaje (caminar, bailar, saludar...) y páusalo."] = "Embaixo do modelo, escolha o que seu personagem faz (andar, dançar, acenar...) e pause.",
	["Abalorio"] = "Berloque",
	["Abalorios"] = "Berloques",
	["Abandonar"] = "Abandonar",
	["Abandonar marcadas (%d)"] = "Abandonar marcadas (%d)",
	["Abandonaste %d misiones"] = "Você abandonou %d missões",
	["Abierta"] = "Aberta",
	["Abiertas"] = "Abertos",
	["Abrazo vampírico: tu daño de sombras te cura."] = "Abraço Vampírico: seu dano de Sombra cura você.",
	["Abre Heridas profundas."] = "Abre Feridas Profundas.",
	["Abre Paisaje y gráficos"] = "Abre Paisagem e gráficos",
	["Abre Recolección. Con «ruta», crea y sigue una ruta de farmeo en tu zona."] = "Abre Coleta. Com “ruta”, cria e segue uma rota de farm na sua zona.",
	["Abre desde el sigilo para empezar con ventaja."] = "Comece da furtividade para sair na frente.",
	["Abre el mapa del juego en esta misma zona. En combate el mapa del juego no se abre desde Alfa."] = "Abre o mapa do jogo nesta mesma zona. Em combate, o mapa do jogo não abre pelo Alfa.",
	["Abre el mapa y haz clic derecho (o Mayús+clic) donde quieras uno: le pones nombre, ícono y color, y la flecha te lleva cuando quieras. En el mapa del juego, Mayús+clic derecho."] = "Abra o mapa e clique com o botão direito (ou Shift+clique) onde quiser um: dê nome, ícone e cor, e a seta leva você quando quiser. No mapa do jogo, Shift+clique direito.",
	["Abre el modo pesca (aquí, con /alfa pesca o al ponerte la caña) y pulsa %s: tu tecla te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Abra o modo pesca (aqui, com /alfa pesca ou ao equipar a vara) e aperte %s: sua tecla coloca seu equipamento, a isca, lança e recolhe quando espirra água.",
	["Abre el modo pesca y elige tu tecla: te pone el equipo, el cebo, lanza y recoge cuando salpica."] = "Abra o modo pesca e escolha sua tecla: ela coloca seu equipamento, a isca, lança e recolhe quando espirra água.",
	["Abre el modo pesca y pulsa tu tecla: lo que saques aparece aquí."] = "Abra o modo pesca e aperte sua tecla: o que você pescar aparece aqui.",
	["Abre la Cocina del juego (el botón lo hace) y vuelve a pulsar."] = "Abra a janela de Culinária do jogo (o botão faz isso) e aperte de novo.",
	["Abre la Enciclopedia y en la ficha del objeto toca «Agregar a mi ruta»."] = "Abra a Enciclopédia e, na ficha do item, toque em “Adicionar à minha rota”.",
	["Abre la casa de subastas para escanear."] = "Abra a casa de leilões para escanear.",
	["Abre la casa de subastas y pulsa «Escanear con Alfa» para saber cuánto valen tus objetos."] = "Abra a casa de leilões e clique em “Escanear com o Alfa” para saber quanto valem seus itens.",
	["Abre la guía de Alfa que te lleva a conseguir este objeto."] = "Abre o guia do Alfa que leva você a conseguir este item.",
	["Abre la pelea a distancia antes de que llegue."] = "Comece a luta à distância antes que ele chegue.",
	["Abre la pelea: te acerca al enemigo y te da ira."] = "Abre a luta: leva você até o inimigo e dá raiva.",
	["Abre la siguiente fila."] = "Abre a próxima fileira.",
	["Abre la ventana Historias."] = "Abre a janela Histórias.",
	["Abre la ventana de talentos del juego una vez o espera unos segundos: en cuanto Alfa la lea, te dice qué poner. Mientras, abajo ves tu build."] = "Abra a janela de talentos do jogo uma vez ou espere uns segundos: assim que o Alfa ler, ele diz o que pegar. Enquanto isso, sua build aparece abaixo.",
	["Abre la ventana de tu profesión una vez y Alfa leerá tus recetas para decirte cuáles te dejan ganancia."] = "Abra a janela da sua profissão uma vez e o Alfa vai ler suas receitas para dizer quais dão lucro.",
	["Abre la ventana principal de Alfa."] = "Abre a janela principal do Alfa.",
	["Abre o cierra el mapa de Alfa"] = "Abre ou fecha o mapa do Alfa",
	["Abre siempre con Cargar y pon Desgarrar al empezar la pelea."] = "Sempre comece com Investida e aplique Dilacerar no início da luta.",
	["Abre siempre desde el sigilo con tu ataque más fuerte."] = "Sempre comece da furtividade com o seu ataque mais forte.",
	["Abre su ficha."] = "Abre a ficha.",
	["Abre un susurro con tu mensaje listo. Si no está conectado, el juego te lo dirá."] = "Abre um sussurro com a sua mensagem pronta. Se a pessoa não estiver conectada, o jogo avisa.",
