	["Abrumar hace crítico mucho más seguido."] = "Sobrepujar acerta crítico com muito mais frequência.",
	["Acabas de vencer a un enemigo: este ataque es gratis y te cura."] = "Você acabou de vencer um inimigo: este ataque é grátis e cura você.",
	["Accesos"] = "Atalhos",
