	["Acento propio (elegido en Ajustes)"] = "Cor de destaque própria (escolhida em Opções)",
	["Acento: %s"] = "Destaque: %s",
	["Acepta invitaciones de grupo de tus amigos y de tu hermandad."] = "Aceita convites de grupo dos seus amigos e da sua guilda.",
	["Acepta por ti"] = "Aceita por você",
	["Acepta una invocación al momento, salvo en combate."] = "Aceita uma invocação na hora, exceto em combate.",
	["Acepta una resurrección en cuanto se puede. Nunca en Hardcore."] = "Aceita uma ressurreição assim que possível. Nunca no Hardcore.",
	["Acepta y entrega las demás (normales, diarias y semanales). Nunca las grises ni las que piden oro o materiales."] = "Aceita e entrega as demais (normais, diárias e semanais). Nunca as cinzas nem as que pedem ouro ou materiais.",
	["Aceptar"] = "OK",
