	["Acercar"] = "Aproximar",
	["Acomoda tus marcos"] = "Ajeite seus quadros",
	["Activa máquinas en las paredes que sueltan bombas que caminan: pulsa el botón junto a la máquina para apagarla, o maten las bombas antes de que lleguen."] = "Ele liga máquinas nas paredes que soltam bombas que andam: aperte o botão ao lado da máquina para desligá-la, ou matem as bombas antes que cheguem.",
	["Activar el modo limpio"] = "Ativar o modo limpo",
	["Activo"] = "Ativo",
	["Actual"] = "Atual",
	["Actualizar mi guía"] = "Atualizar meu guia",
	["Actualizar mis barras"] = "Atualizar minhas barras",
	["Actualízala con la app de CurseForge o con el zip más reciente y luego usa /reload."] = "Atualize com o app do CurseForge ou com o zip mais recente e depois use /reload.",
	["Actualízalo con la app de CurseForge o con el zip más reciente y luego reinicia el juego o usa /reload."] = "Atualize com o app do CurseForge ou com o zip mais recente e depois reinicie o jogo ou use /reload.",
	["Además del ícono, un brillo dorado que late alrededor de su barra."] = "Além do ícone, um brilho dourado que pulsa ao redor da barra.",
	["Afinar siempre"] = "Sempre aplicar nitidez",
	["Aflicción"] = "Suplício",
	["Aflicción para subir"] = "Suplício para subir de nível",
	["Agarras a varios enemigos a la vez."] = "Você segura vários inimigos de uma vez.",
	["Agilidad"] = "Agilidade",
	["Agrega la primera: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota."] = "Adicione a primeira: um item, ouro, uma profissão, um lugar, uma missão, um nível ou uma nota.",
	["Agrega tramos arriba: Alfa elige las misiones por ti."] = "Adicione trechos acima: o Alfa escolhe as missões por você.",
	["Agrega una línea con el objetivo de esa unidad; si te tiene a ti, lo dice."] = "Adiciona uma linha com o alvo dessa unidade; se o alvo for você, ele avisa.",
	["Agregada"] = "Adicionada",
