	["Andorhal era el granero de Lordaeron. Kel'Thuzad repartió ahí grano apestado y la plaga se extendió por todo el reino."] = "Andorhal era o celeiro de Lordaeron. Kel'Thuzad distribuiu ali grãos empesteados e a praga se espalhou por todo o reino.",
	["Anillos"] = "Anéis",
