	["Anterior"] = "Anterior",
	["Antes de atacar, mira quién está cerca. Pelear con uno a la vez es más seguro."] = "Antes de atacar, veja quem está por perto. Lutar com um de cada vez é mais seguro.",
	["Antes de empezar, unas palabras de la manada."] = "Antes de começar, umas palavras da matilha.",
	["Antes de entrar"] = "Antes de entrar",
	["Antes de pelear"] = "Antes da luta",
	["Antes de pelear: abre con Piroexplosión, tu hechizo más fuerte."] = "Antes da luta: comece com Ignimpacto, seu feitiço mais forte.",
	["Antes de salir de caza, configura Alfa a tu medida: el idioma, cómo se ve, qué hace sola por ti y si quieres que la manada te vea en el mapa del juego."] = "Antes de sair para caçar, configure o Alfa do seu jeito: o idioma, a aparência, o que ele faz sozinho por você e se a matilha pode ver você no mapa do jogo.",
	["Antes esto era un pantano. La magia del portal y la guerra lo dejaron rojo, seco y sin vida."] = "Antes isto era um pântano. A magia do portal e a guerra o deixaram vermelho, seco e sem vida.",
	["Antes hay que hacer otra misión"] = "Antes é preciso fazer outra missão",
	["Antes necesitas"] = "Antes você precisa",
	["Antes necesitas otra misión"] = "Precisa de outra missão antes",
	["Antes pide %s (%s)"] = "Antes pede %s (%s)",
	["Antes: %s"] = "Antes: %s",
	["Antes: %s."] = "Antes: %s.",
	["Anunciar"] = "Anunciar",
	["Anunciar en el chat"] = "Anunciar no chat",
	["Anunciar en el grupo"] = "Anunciar no grupo",
	["Apaga la viñeta, el grano, las barras y el tinte de un clic."] = "Desliga a vinheta, o granulado, as barras e o tom com um clique.",
	["Apagada"] = "Desativada",
	["Apagadas"] = "Desativadas",
	["Apagado"] = "Desativado",
	["Apagado, el grano se queda quieto."] = "Desligado, o granulado fica parado.",
	["Apagado, solo las acepta y la entrega la haces tú."] = "Desativado, só aceita as missões e quem entrega é você.",
	["Apagados"] = "Desativados",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "Aparece no fim do evento do Discípulo de Naralex: proteja o druida enquanto ele caminha.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "Aparece ao tocar o gongo pela terceira vez, depois de duas ondas de aranhas.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "Aparece com uma missão da Horda (um objeto na água). Lança gelo.",
	["Aparece en cuanto termines la bienvenida de Alfa."] = "Ela aparece assim que você terminar as boas-vindas do Alfa.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "Aparece no evento da explosivista: proteja-a enquanto chegam ondas de troggs.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "Aparecem quadros de exemplo: arraste-os para onde quiser e ajuste o tamanho. Assim seu grupo vai aparecer.",
	["Aplaudir"] = "Aplaudir",
	["Aplica la nitidez de abajo aunque no uses el escalado de resolución."] = "Aplica a nitidez abaixo mesmo sem usar a escala de resolução.",
	["Aplicar"] = "Aplicar",
	["Aplicar %d puntos"] = "Aplicar %d pontos",
	["Aprende Cocina con un instructor."] = "Aprenda Culinária com um instrutor.",
	["Aprende Cocina para encender fogatas."] = "Aprenda Culinária para acender fogueiras.",
	["Aprende Pesca"] = "Aprenda Pesca",
	["Aprende Pesca con un instructor"] = "Aprenda Pesca com um instrutor",
	["Aprende Pesca con un instructor de pesca y compra una caña: la guía te lleva."] = "Aprenda Pesca com um instrutor de pesca e compre uma vara: o guia leva você até lá.",
	["Aprende Pesca con un instructor, compra una caña y pesca en tu zona de inicio o en la capital. Pide el rango Oficial desde 50."] = "Aprenda Pesca com um instrutor, compre uma vara e pesque na sua zona inicial ou na capital. Peça a faixa Artesão a partir de 50.",
	["Aprende equitación con %s"] = "Aprenda montaria com %s",
	["Aprende las dos, consigue una caña y cocina lo que pescas hasta 75."] = "Aprenda as duas, consiga uma vara e cozinhe o que pescar até 75.",
	["Aprender %s"] = "Aprender %s",
	["Aprender de tus búsquedas"] = "Aprender com suas buscas",
	["Aprender una profesión o llegar a un nivel en ella."] = "Aprender uma profissão ou chegar a um nível nela.",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "Você aprendeu um feitiço que combina melhor com seus cliques:",
	["Aprendiz"] = "Aprendiz",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "Aprenda com o instrutor da sua classe, em qualquer capital.",
	["Apágalo si no quieres que Alfa toque tus teclas, tu equipo ni tus ajustes al pescar."] = "Desligue se não quiser que o Alfa mexa nas suas teclas, no seu equipamento nem nas suas opções ao pescar.",
	["Aquí"] = "Aqui",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Aqui vão aparecer os outros módulos do Alfa (bolsas, rotas, mundo e mais) assim que forem instalados.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "Aqui o jogo não informa sua posição (por exemplo, dentro de uma masmorra).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "Aqui o jogo não deixa compartilhar nada. Ao sair, seu rastro volta a sair sozinho.",
	["Aquí estoy, como siempre. Nunca dejo a nadie atrás."] = "Aqui estou, como sempre. Nunca deixo ninguém para trás.",
	["Aquí está el Portal Oscuro: por él cruzó la Horda desde Draenor para invadir Azeroth en la Primera Guerra."] = "Aqui está o Portal Negro: por ele a Horda atravessou de Draenor para invadir Azeroth na Primeira Guerra.",
	["Aquí está la tumba de Uther el Iluminado, el maestro de Arthas. Murió a manos de su propio alumno, defendiendo las cenizas del rey Terenas."] = "Aqui está o túmulo de Uther, o Arauto da Luz, mestre de Arthas. Morreu pelas mãos do próprio aluno, defendendo as cinzas do rei Terenas.",
	["Aquí la lees completa: cómo empieza, qué te piden y cómo termina."] = "Aqui você a lê completa: como começa, o que pedem e como termina.",
	["Aquí no hay nodos que recolectar"] = "Aqui não há pontos para coletar",
	["Aquí sale por qué se activó la habilidad."] = "Aqui aparece por que a habilidade foi ativada.",
	["Aquí ves cuántas llevas, dónde sale y qué hacer con ella."] = "Aqui você vê quantos tem, de onde vem e o que fazer com ele.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "Aqui você vê tudo o que precisa saber e o que fazer depois.",
	["Aquí: %s %.1f, %.1f. Se guarda este punto."] = "Aqui: %s %.1f, %.1f. Este ponto fica salvo.",
	["Arañazo: sangrado con el tiempo."] = "Rasgar: sangramento ao longo do tempo.",
	["Arcano"] = "Arcano",
	["Arcano para subir"] = "Arcano para subir de nível",
	["Arco"] = "Arco",
	["Arcos, ballestas y armas de fuego"] = "Arcos, bestas e armas de fogo",
	["Arena"] = "Areia",
	["Arma"] = "Arma",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "Monta com a sua rota o que você precisa para poder pegá-la: o nível ou as missões anteriores.",
	["Arma de asta"] = "Arma de Haste",
	["Arma de dos manos"] = "Arma de duas mãos",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "Arma de duas mãos, selos e julgamentos: o paladino que melhor sobe de nível sozinho.",
	["Arma de fuego"] = "Arma de Fogo",
	["Arma de puño"] = "Arma de Punho",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "Monta o plano para fechar as missões do seu registro e leva você a cada uma.",
	["Arma tu grupo de 5 (buscador de grupos o tu manada)."] = "Monte seu grupo de 5 (localizador de grupos ou sua matilha).",
	["Arma tu primer plan"] = "Monte seu primeiro plano",
