	["Asesinato para subir"] = "Assassinato para subir de nível",
	["Asistente"] = "Assistente",
	["Aspecto"] = "Aspecto",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "Ele amedronta todos que estão perto: se você for amedrontado, tente não correr para outras celas.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "Ele amedronta e põe os jogadores para dormir: se você for amedrontado, tente não correr para mais inimigos.",
