	["Cada frase sale tres veces como mucho. Con esto vuelven a salir desde el principio."] = "Cada frase aparece no máximo três vezes. Com isto elas voltam a aparecer desde o começo.",
	["Cada golpe crítico deja al enemigo sangrando: daño extra sin hacer nada."] = "Cada acerto crítico deixa o inimigo sangrando: dano extra sem fazer nada.",
	["Cada lugar conocido donde aparece un enemigo raro."] = "Cada lugar conhecido onde aparece um inimigo raro.",
	["Cada misión que terminas te hace más fuerte."] = "Cada missão que você termina deixa você mais forte.",
	["Cada nivel"] = "A cada nível",
	["Cada preajuste llena tus clics con los hechizos que ya sabes. Después cambias lo que quieras en la página Curación."] = "Cada predefinição preenche seus cliques com os feitiços que você já sabe. Depois você muda o que quiser na página Cura.",
	["Cada reto da 1 punto. Al salir Forever hay %d retos, y cada personaje puede gastar hasta %d."] = "Cada desafio dá 1 ponto. No lançamento do Forever há %d desafios, e cada personagem pode gastar até %d.",
	["Cairne Pezuña de Sangre gobierna desde Cima del Trueno, aunque Magatha, de los Tótem Siniestro, no lo quiere tanto como aparenta."] = "Cairne Casco Sangrento governa do Penhasco do Trovão, embora Magatha, dos Temível Totem, não goste tanto dele quanto aparenta.",
