	["Copia este texto (Ctrl+C) y pásalo a tu manada. Lo pegan en Importar."] = "Copie este texto (Ctrl+C) e passe para sua matilha. Eles colam em Importar.",
	["Copia la cadena de abajo y pásala por el chat o por Discord: con Alfa la pegan en Importar y tienen tu mismo build."] = "Copie o texto abaixo e passe pelo chat ou pelo Discord: com o Alfa, colam em Importar e ficam com a mesma build que você.",
	["Copia tu mapa al clic para lanzar de Blizzard, así curas igual en sus marcos de grupo. Si el juego no lo deja, abre su ventana para que lo hagas ahí."] = "Copia o seu mapa para o clique para lançar da Blizzard, para você curar do mesmo jeito nos quadros de grupo dela. Se o jogo não deixar, a janela dela abre para você fazer ali.",
