	["Cuántas capas de sombra se dibujan: con más capas, las sombras nítidas llegan más lejos."] = "Quantas camadas de sombra são desenhadas: com mais camadas, as sombras nítidas vão mais longe.",
	["Cuántas casillas caben en cada fila."] = "Quantos espaços cabem em cada fileira.",
