	["Cuántas habilidades después"] = "Quantas habilidades depois",
	["Cuánto daño quita cada bloqueo; también sube el daño de Embate con escudo."] = "Quanto dano cada bloqueio absorve; também aumenta o dano de Shield Slam.",
	["Cuánto dura un aviso en pantalla"] = "Quanto tempo um aviso fica na tela",
	["Cuánto falta para tu siguiente golpe automático, con cada mano. Ayuda a meter Embate o Golpe heroico sin perder golpes."] = "Quanto falta para o seu próximo golpe automático, com cada mão. Ajuda a encaixar Slam ou Golpe Heroico sem perder golpes.",
	["Cuánto más brillan las luces que en una pantalla normal. El juego no pasa del máximo de tu monitor."] = "Quanto as luzes brilham mais que numa tela normal. O jogo nunca passa do máximo do seu monitor.",
	["Cuánto oro"] = "Quanto ouro",
	["Cuánto pasto, flores y hierbas cubren el suelo."] = "Quanta grama, flores e ervas cobrem o chão.",
