	["Daga"] = "Adaga",
	["Dale de comer a tu mascota para que esté contenta y pegue más."] = "Alimente seu ajudante para ele ficar feliz e bater mais.",
	["Dale de comer para que esté feliz: pega más fuerte."] = "Alimente-o para ele ficar feliz: ele bate mais forte.",
	["Dar a las barras el estilo de Alfa"] = "Dar às barras o estilo do Alfa",
	["Dar al chat el estilo de Alfa"] = "Dar ao chat o estilo do Alfa",
	["Dar al minimapa el estilo de Alfa"] = "Dar ao minimapa o estilo do Alfa",
	["Darnassus está en las ramas de Teldrassil. La suma sacerdotisa Tyrande Susurravientos gobierna desde el Templo de la Luna."] = "Darnassus fica nos galhos de Teldrassil. A suma sacerdotisa Tyrande Murmuréquia governa do Templo da Lua.",
	["Datos"] = "Dados",
	["Datos curiosos de Lya, escritos por Alfa."] = "Curiosidades da Lya, escritas pelo Alfa.",
	["Daño"] = "Dano",
	["Daño a distancia"] = "Dano à distância",
	["Daño con el tiempo: ponla al empezar la pelea."] = "Dano ao longo do tempo: aplique ao começar a luta.",
