	["Daño directo de tus armas y habilidades."] = "Dano direto das suas armas e habilidades.",
	["Daño en grupo de cinco: pegar fuerte sin robarle los monstruos al tanque."] = "Dano em grupo de cinco: bater forte sem roubar os monstros do tanque.",
	["Daño extra después de recibir críticos."] = "Dano extra depois de receber críticos.",
