	["Dentro de la mazmorra"] = "Dentro da masmorra",
	["Dentro de mazmorras y ciudades no hay nodos. Sal al mundo y tu ruta se arma en un clic."] = "Dentro de masmorras e cidades não há pontos. Saia para o mundo e sua rota se monta com um clique.",
