	["Después de él se encienden los braseros del altar y llegan oleadas de enemigos: prepárense antes."] = "Depois dele, os braseiros do altar se acendem e chegam ondas de inimigos: preparem-se antes.",
	["Después del combate"] = "Depois do combate",
	["Después del primer jefe, un prisionero de tu facción abre la puerta: háblale."] = "Depois do primeiro chefe, um prisioneiro da sua facção abre a porta: fale com ele.",
