	["Devolver los avisos a su lugar"] = "Devolver os avisos ao lugar",
	["Devuelve cada ajuste que Alfa tocó al valor que tenía antes y deja de mantenerlos."] = "Devolve cada opção que o Alfa mexeu ao valor que tinha antes e deixa de mantê-las.",
	["Devuelve los valores que tenías antes del último preajuste."] = "Devolve os valores que você tinha antes da última predefinição.",
	["Diario"] = "Diário",
	["Diario de mazmorras"] = "Diário de masmorras",
	["Diario de pesca"] = "Diário de pesca",
	["Dibuja el arte completo de cada zona recortado a su forma, con las texturas de detalle incluidas. Sin ellas el mapa sigue completo, solo más suave entre zona y zona."] = "Desenha a arte completa de cada zona recortada no formato dela, com as texturas de detalhe incluídas. Sem elas o mapa continua completo, só mais suave entre uma zona e outra.",
	["Dibuja la ruta hasta tu objetivo: por dónde caminar, volar o navegar."] = "Desenha a rota até o seu objetivo: por onde andar, voar ou navegar.",
	["Dice en el chat qué misión perderías y te deja aceptarla a ti."] = "Diz no chat qual missão você perderia e deixa você aceitá-la.",
	["Dicen que el Bosque del Ocaso se oscureció por estar tan cerca de Karazhan, y desde entonces vive en penumbra."] = "Dizem que a Floresta do Crepúsculo escureceu por estar tão perto de Karazhan, e desde então vive na penumbra.",
	["Diestro"] = "Habilidoso",
	["Diez mil años atrás, Illidan creó en la cima de Hyjal un nuevo Pozo de la Eternidad, y sobre él se plantó Nordrassil."] = "Dez mil anos atrás, Illidan criou no topo de Hyjal uma nova Nascente da Eternidade, e sobre ela foi plantada Nordrassil.",
