	["Encendido"] = "Ativado",
	["Encendido: el doble clic mientras pescas lanza de nuevo y, con Mayús, Ctrl o Alt, recoge. Apagado: al revés."] = "Ativado: o clique duplo enquanto pesca lança de novo e, com Shift, Ctrl ou Alt, recolhe. Desativado: o contrário.",
	["Enciclopedia"] = "Enciclopédia",
