	["Escudo y defensa: aguantas a todos los monstruos para que tu grupo no sufra."] = "Escudo e defesa: você segura todos os monstros para o seu grupo não sofrer.",
	["Escudo y luz sagrada: un tanque muy resistente que recupera su propio maná."] = "Escudo e luz sagrada: um tanque muito resistente que recupera a própria mana.",
	["Escudos y curas preventivas: aguantas mucho y apoyas al grupo."] = "Escudos e curas preventivas: você aguenta muito e apoia o grupo.",
	["Ese build es para otra clase."] = "Essa build é para outra classe.",
	["Ese talento necesita antes otro talento completo (la flecha del árbol)."] = "Esse talento precisa antes de outro talento completo (a seta da árvore).",
