	["Esta clase no tiene pesos de estadísticas."] = "Esta classe não tem pesos de atributos.",
	["Esta explicación no saldrá más. En Combate puedes volver a encenderlas."] = "Esta explicação não vai aparecer mais. Em Combate você pode religá-las.",
	["Esta sesión"] = "Esta sessão",
	["Esta sesión, por recurso"] = "Esta sessão, por recurso",
	["Esta sesión: %d capturas de %d lanzamientos. Desde siempre: %d."] = "Esta sessão: %d capturas em %d lançamentos. Desde sempre: %d.",
	["Esta sesión: %s"] = "Esta sessão: %s",
	["Esta subasta no permite el escaneo completo."] = "Esta casa de leilões não permite o escaneamento completo.",
	["Esta va de %s y %s… ¿Te la cuento?"] = "Esta é sobre %s e %s… Quer que eu conte?",
	["Esta va de %s y de lobos… me toca de cerca. ¿Te la cuento?"] = "Esta é sobre %s e lobos… me toca de perto. Quer que eu conte?",
	["Establos"] = "Mestre de Estábulo",
	["Estadísticas"] = "Atributos",
	["Este aviso ya no mostrará texto: solo el ícono. En Combate puedes volver a encenderlos."] = "Este aviso não vai mais mostrar texto: só o ícone. Em Combate você pode religá-los.",
	["Este banco no vende más espacio."] = "Este banco não vende mais espaço.",
	["Este build pega muchísimo, pero aguanta poco: elige bien cuándo entrar."] = "Esta build bate muito, mas aguenta pouco: escolha bem a hora de entrar.",
	["Este clic no hace nada. Elígele algo en Tu ratón, en la página Curación."] = "Este clique não faz nada. Escolha algo para ele em Seu mouse, na página Cura.",
	["Este cliente no carga los mosaicos del minimapa: se ve el arte pintado."] = "Este cliente não carrega os mosaicos do minimapa: aparece a arte pintada.",
	["Este cliente no da el arte del mapa"] = "Este cliente não fornece a arte do mapa",
	["Este cliente no deja compartir"] = "Este cliente não deixa compartilhar",
	["Este cliente no deja compartir marcadores."] = "Este cliente não deixa compartilhar marcadores.",
	["Este cliente no deja copiar tu mapa solo: se abrió la ventana de clic para lanzar de Blizzard para que lo armes ahí."] = "Este cliente não consegue copiar o seu mapa sozinho: a janela de clique para lançar da Blizzard foi aberta para você montar ali.",
	["Este cliente no tiene %d de estos ajustes: no se muestran."] = "Este cliente não tem %d destas opções: elas não aparecem.",
	["Este cliente no tiene el clic para lanzar de Blizzard. Tus clics funcionan en los marcos de Alfa."] = "Este cliente não tem o clique para lançar da Blizzard. Seus cliques funcionam nos quadros do Alfa.",
	["Este cliente no tiene la ventana del Legado."] = "Este cliente não tem a janela do Legado.",
	["Este paso"] = "Este passo",
	["Este paso no tiene punto en el mapa."] = "Este passo não tem ponto no mapa.",
	["Este talento no está en tu build."] = "Este talento não está na sua build.",
	["Este tramo quedó vacío."] = "Este trecho ficou vazio.",
	["Estilo"] = "Estilo",
	["Estilo de las barras"] = "Estilo das barras",
	["Estilo del chat"] = "Estilo do chat",
	["Estilo del mapa"] = "Estilo do mapa",
	["Estilo del minimapa"] = "Estilo do minimapa",
	["Estilo y sonido"] = "Estilo e som",
	["Esto no se puede cambiar en combate. Inténtalo al terminar la pelea."] = "Isto não pode ser mudado em combate. Tente quando a luta acabar.",
	["Esto no se puede vincular."] = "Isto não pode ser linkado.",
	["Estos filtros los dibuja Alfa, no el juego: quedan detrás de toda la interfaz (nunca la tapan) y también se ven con la interfaz oculta (Alt+Z), para tus capturas."] = "Estes filtros são desenhados pelo Alfa, não pelo jogo: ficam atrás de toda a interface (nunca a cobrem) e também aparecem com a interface oculta (Alt+Z), para suas capturas de tela.",
	["Está en el Cementerio. Pone un dolor de sombras que hace daño con el tiempo."] = "Fica no Cemitério. Coloca uma dor sombria que causa dano ao longo do tempo.",
	["Está en el agua, junto a la cascada: llévenlo a tierra antes de pelear."] = "Fica na água, junto da cachoeira: levem-no para a terra antes de lutar.",
	["Está en la Armería. Cuando grita, gira con su hacha y golpea a todos los que están cerca: aléjate."] = "Fica no Arsenal. Quando grita, gira com o machado e acerta todos que estão perto: afaste-se.",
	["Está en la Biblioteca y llega con sus perros: mátenlos primero o usen ataques en área."] = "Fica na Biblioteca e chega com seus cães: matem os cães primeiro ou usem ataques em área.",
	["Está escondido en la Catedral. Pone maldiciones y se cura: interrúmpelo."] = "Fica escondido na Catedral. Lança maldições e se cura: interrompa.",
	["Está lleno de jabaespines y sus túneles de espinos: tiren de pocos a la vez."] = "É cheia de javatuscos e seus túneis de espinhos: puxem poucos de cada vez.",
	["Está rodeado de goblins que trabajan: tiren a esos goblins primero, de uno en uno."] = "Ele está cercado de goblins trabalhando: puxem esses goblins primeiro, um de cada vez.",
	["Está rodeado de múrlocs: tiren a sus amigos antes que a él."] = "Ele está cercado de murlocs: puxem os amigos dele antes dele.",
	["Estás aquí"] = "Você está aqui",
	["Estás con un banquero: desde su ventana depositas lo que quieras con un clic."] = "Você está com um bancário: pela janela dele você deposita o que quiser com um clique.",
	["Estás dentro"] = "Você está dentro",
	["Estás descansando"] = "Você está descansando",
	["Estás en combate. Los talentos solo se cambian fuera de combate: termina la pelea y vuelve a intentarlo."] = "Você está em combate. Os talentos só mudam fora de combate: termine a luta e tente de novo.",
	["Estás en combate: busca el equipo al terminar la pelea."] = "Você está em combate: procure o equipamento quando a luta acabar.",
	["Estás en combate: lo que cambies se aplica al salir."] = "Você está em combate: o que mudar vale quando você sair.",
	["Estás en combate: lo que cambies se aplica en cuanto termine."] = "Você está em combate: o que mudar se aplica assim que ele terminar.",
	["Estás en combate: se aplica en cuanto termine."] = "Você está em combate: se aplica assim que ele terminar.",
	["Estás en combate: tus cambios se aplican en cuanto termine."] = "Você está em combate: suas mudanças se aplicam assim que ele terminar.",
	["Estás en grupo y otro aguanta al enemigo: apuñálalo por la espalda."] = "Você está em grupo e outro segura o inimigo: apunhale-o pelas costas.",
	["Estás en grupo y otro aguanta al enemigo: trízalo por la espalda."] = "Você está em grupo e outro segura o inimigo: retalhe-o pelas costas.",
	["Estás en la ciudad y hay habilidades por entrenar (%d). ¡Aprovecha!"] = "Você está na cidade e há habilidades para treinar (%d). Aproveite!",
	["Estás en sigilo: Premeditación te da puntos de combo."] = "Você está na furtividade: Premeditação dá pontos de combo.",
