	["Junta 100 capturas."] = "Junte 100 capturas.",
	["Junta 1000 capturas."] = "Junte 1000 capturas.",
	["Junta 500 capturas."] = "Junte 500 capturas.",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Junte dois monstros e use Sweeping Strikes: assim você sobe mais rápido.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Junte dois ou três monstros, use Trovoada e Revanche: você sobe com segurança e sem descansar.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Junta as pilhas e organiza seus itens com um clique.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Junta as pilhas e organiza seus itens. Não funciona em combate.",
	["Junta materiales de tu profesión donde más hay."] = "Junte materiais da sua profissão onde há mais.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Junte materiais da sua profissão, com algumas missões de XP no meio.",
	["Junta misiones de la misma zona: haces varias en un solo viaje."] = "Junte missões da mesma zona: você faz várias em uma só viagem.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Junte vários monstros: seus golpes sagrados alcançam todos.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Juntando tudo do jogo. Só na primeira vez que você abre.",
	["Juntar %s"] = "Juntar %s",
	["Juntar los materiales de mi profesión"] = "Juntar os materiais da minha profissão",
	["Juntar materiales para vender"] = "Juntar materiais para vender",
	["Juntar nodos cercanos al alejar"] = "Juntar pontos próximos ao afastar",
	["Juntar oro"] = "Juntar ouro",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Ao lado da lupa do mapa do jogo: as camadas, o modo limpo e “Mapa do Alfa” para mudar para o do Alfa.",
	["Karazhan, la torre de Medivh, el último Guardián, se levanta sobre un cruce de líneas de magia natural."] = "Karazhan, a torre de Medivh, o último Guardião, ergue-se sobre um cruzamento de linhas de energia naturais.",
	["Kargath, el campamento de la Horda, lleva el nombre de un viejo caudillo orco del clan Mano Destrozada."] = "Kargath, o acampamento da Horda, leva o nome de um velho chefe orc do clã Mão Despedaçada.",
	["La %s también está en el menú del juego."] = "A opção %s também está no menu do jogo.",
	["La Abadía de Villanorte es de las más antiguas del reino; ahí empiezan su camino muchos aventureros humanos."] = "A Abadia de Vila Norte é uma das mais antigas do reino; ali muitos aventureiros humanos começam seu caminho.",
	["La Alianza nació en la Segunda Guerra, cuando los reinos humanos, los enanos y los altos elfos se unieron contra la Horda."] = "A Aliança nasceu na Segunda Guerra, quando os reinos humanos, os anões e os altos elfos se uniram contra a Horda.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Shift+B, a tecla de cada bolsa e os mercadores abrem a janela do Alfa. Desative para voltar às do jogo.",
	["La Capilla de la Esperanza de la Luz resistió a la Plaga en una batalla legendaria; hoy es el gran refugio del Alba Argenta."] = "A Capela Esperança da Luz resistiu ao Flagelo numa batalha lendária; hoje é o grande refúgio da Aurora Argêntea.",
	["La Catedral de la Luz es el corazón de la fe en Ventormenta; sus sacerdotes atienden a toda la Alianza."] = "A Catedral da Luz é o coração da fé em Ventobravo; seus sacerdotes atendem toda a Aliança.",
	["La Cruzada Escarlata nació del dolor de Lordaeron tras la plaga, pero su odio la volvió tan cruel como lo que combate."] = "A Cruzada Escarlate nasceu da dor de Lordaeron depois da praga, mas seu ódio a deixou tão cruel quanto aquilo que combate.",
	["La Cruzada Escarlata tiene aquí su monasterio. Para ellos todo no-muerto debe arder, también los Renegados."] = "A Cruzada Escarlate tem aqui seu monastério. Para eles todo morto-vivo deve queimar, inclusive os Renegados.",
	["La Garganta de Fuego quedó así por culpa del Hierro Negro: su hechicero-thane Thaurissan invocó a Ragnaros y la tierra se incendió."] = "A Garganta Abrasadora ficou assim por culpa dos Ferro Negro: seu feiticeiro-thane Thaurissan invocou Ragnaros e a terra pegou fogo.",
	["La Gran Forja, en el corazón de Forjaz, nunca se apaga."] = "A Grande Forja, no coração de Altaforja, nunca se apaga.",
	["La Guardia Nocturna es la milicia de Villa Oscura: protege el pueblo de lobos, no-muertos y worgen."] = "A Vigília Noturna é a milícia de Vila Sombria: protege o povoado de lobos, mortos-vivos e worgens.",
	["La Hermandad del Torio son enanos Hierro Negro que se separaron de su clan. Son maestros herreros y negocian con quien los respete."] = "A Irmandade do Tório são anões Ferro Negro que se separaram do clã. São mestres ferreiros e negociam com quem os respeite.",
	["La Horda arrasó Ventormenta en la Primera Guerra. Los albañiles que la reconstruyeron no recibieron su pago, y de ese enojo nació la Hermandad Defias."] = "A Horda arrasou Ventobravo na Primeira Guerra. Os pedreiros que a reconstruíram nunca foram pagos, e dessa raiva nasceu a Irmandade Défias.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría no mapa",
	["La Jauría: estado"] = "La Jauría: estado",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: sua matilha no mapa, Seguir e o clã (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: seus comandos",
	["La Legión Ardiente es el ejército de demonios de Sargeras, un titán caído que quiere quemar toda la creación."] = "A Legião Ardente é o exército de demônios de Sargeras, um titã caído que quer queimar toda a criação.",
	["La Liga de Expedicionarios, los arqueólogos de Forjaz, busca por todo el mundo las ruinas que cuenten el origen de los enanos."] = "A Liga dos Exploradores, os arqueólogos de Altaforja, procura pelo mundo todo as ruínas que contem a origem dos anões.",
	["La Masacre fue Eldre'Thalas, una ciudad de los elfos Altonato de antes de la Gran División."] = "Gládio Cruel foi Eldre'Thalas, uma cidade dos elfos Bem-nascidos de antes da Grande Cisão.",
	["La Milicia Popular de la Colina del Centinela la formaron los propios granjeros cuando Ventormenta dejó de mandar soldados."] = "A Milícia Popular da Colina da Sentinela foi formada pelos próprios fazendeiros quando Ventobravo deixou de mandar soldados.",
	["La Montaña Roca Negra se alza entre esta garganta y las Estepas Ardientes. Dentro viven los Hierro Negro, Ragnaros y los dragones negros."] = "A Montanha Rocha Negra se ergue entre esta garganta e as Estepes Ardentes. Lá dentro vivem os Ferro Negro, Ragnaros e os dragões negros.",
	["La Orden de Tirisfal, los magos secretos que elegían al Guardián de Azeroth, tomó su nombre de estos claros. Medivh fue el último Guardián."] = "A Ordem de Tirisfal, os magos secretos que escolhiam o Guardião de Azeroth, tirou seu nome destas clareiras. Medivh foi o último Guardião.",
	["La Plaga es el ejército no-muerto del Rey Exánime. Kel'Thuzad la extendió por Lordaeron con grano infectado."] = "O Flagelo é o exército morto-vivo do Lich Rei. Kel'Thuzad o espalhou por Lordaeron com grãos infectados.",
	["La Sociedad Real de Boticarios trabaja en secreto en una plaga nueva... y no precisamente para los humanos solamente."] = "A Sociedade Real de Boticários trabalha em segredo numa nova praga... e não exatamente só para os humanos.",
	["La ayuda de rotación está apagada"] = "A ajuda de rotação está desativada",
	["La barra con el nombre de la zona y la hora toma los colores y la letra del estilo. Los botones de rastreo, calendario y correo quedan como siempre."] = "A barra com o nome da zona e a hora assume as cores e a fonte do estilo. Os botões de rastreamento, calendário e correio ficam como sempre.",
	["La barra de acción, las barras extra, la de experiencia, el menú y las bolsas toman el estilo que elijas. Solo cambia su aspecto, fuera de combate; al apagarlo vuelven las del juego."] = "A barra de ação, as barras extras, a de experiência, o menu e as bolsas assumem o estilo que você escolher. Só muda a aparência, fora de combate; ao desligar, voltam as do jogo.",
	["La barra de pesca"] = "A barra de pesca",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "A barra de vida com a cor da classe de cada um. Desativado: barra verde e o nome com a cor dele.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "A base incluída traz %s lugares em %d zonas. Você descobriu %s.",
	["La bienvenida con las novedades de esta versión."] = "As boas-vindas com as novidades desta versão.",
	["La básica la venden los instructores y los vendedores de suministros de pesca."] = "A básica é vendida pelos instrutores e pelos vendedores de suprimentos de pesca.",
	["La búsqueda de lugares cercanos no está disponible."] = "A busca de lugares próximos não está disponível.",
	["La cadena no trae talentos válidos."] = "O código não traz talentos válidos.",
	["La caja donde escribes toma el estilo, con el borde de acento mientras escribes. En Clásico WoW queda la del juego."] = "A caixa onde você escreve assume o estilo, com a borda de destaque enquanto você digita. No WoW Clássico fica a do jogo.",
	["La cambiaste fuera de Alfa (menú del juego o consola)."] = "Você a mudou fora do Alfa (menu do jogo ou console).",
	["La cola está vacía."] = "A fila está vazia.",
	["La cura de ese clic pasa al botón central."] = "A cura desse clique passa para o botão do meio.",
	["La cámara no salta hacia ti por cada árbol o poste entre ella y tu personaje."] = "A câmera não pula na sua direção a cada árvore ou poste entre ela e seu personagem.",
	["La cámara se mece un poco con tus pasos."] = "A câmera balança um pouco com seus passos.",
	["La cámara se queda sobre el agua en lugar de meterse."] = "A câmera fica sobre a água em vez de entrar.",
	["La cámara te sigue"] = "A câmera segue você",
	["La de ahora pasa a tus sesiones anteriores."] = "A atual passa para suas sessões anteriores.",
	["La de ahora pasa a tus sesiones anteriores. Tu diario y tus logros no cambian."] = "A atual passa para suas sessões anteriores. Seu diário e suas conquistas não mudam.",
	["La de tu clase mientras subes: cambia sola cuando pongas talentos."] = "A da sua classe enquanto você sobe de nível: muda sozinha quando você distribuir talentos.",
	["La derecha"] = "A direita",
	["La dirección del texto sobre tu personaje."] = "A direção do texto sobre seu personagem.",
	["La empieza un objeto"] = "Começa com um item",
	["La enciclopedia de La Jauría"] = "A enciclopédia de La Jauría",
	["La enciclopedia no puede abrir todavía"] = "A enciclopédia ainda não pode abrir",
	["La entrada de %s"] = "A entrada de %s",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "A entrada de cada masmorra no minimapa, em verde as que você já fez. O mapa-múndi já as marca com “Entradas de masmorras”.",
	["La flecha no está disponible ahora."] = "A seta não está disponível agora.",
	["La flecha que te guía"] = "A seta que guia você",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "A seta se move com o rastro e para quando você chega.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "A seta segue caminhos pelo chão contornando penhascos, água e muros, nos mapas de caminhada do Alfa. Desativado: aponta direto para cada parada.",
	["La flecha sigue en el paso de ahora."] = "A seta continua no passo atual.",
	["La flecha te lleva a %s."] = "A seta leva você até %s.",
	["La flecha te lleva a su entrada."] = "A seta leva você até a entrada.",
	["La flecha te lleva aquí."] = "A seta leva você até aqui.",
	["La flecha te lleva de un lugar al siguiente."] = "A seta leva você de um lugar para o próximo.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "A seta mudou de destino: você parou de seguir %s.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "A seta usa voos e sua Pedra de Regresso quando vale a pena.",
	["La flecha y el camino"] = "A seta e o caminho",
	["La flecha ya no sigue tu ruta de farmeo."] = "A seta não segue mais a sua rota de farm.",
	["La fuerza se cambia en la ventana, en Filtros."] = "A força se muda na janela, em Filtros.",
	["La guarida de Onyxia está en este marjal. Onyxia, hija de Alamuerte, se hace pasar por una noble humana en Ventormenta."] = "O covil de Onyxia fica neste pântano. Onyxia, filha de Asa da Morte, se passa por uma nobre humana em Ventobravo.",
	["La guía en el minimapa"] = "O guia no minimapa",
	["La guía que mejor te queda por tu nivel y donde estás."] = "O guia que mais combina com você pelo seu nível e onde você está.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "O guia que você segue, seu passo atual e tudo sobre guias a um clique.",
	["La guía te lleva a entrenar en %d pasos."] = "O guia leva você para treinar em %d passos.",
	["La guía te lleva a quien recibe cada una."] = "O guia leva você a quem recebe cada uma.",
	["La haces de paso: abre %s."] = "Você faz de passagem: abre %s.",
	["La haré"] = "Vou fazer",
	["La historia"] = "A história",
	["La historia se guarda cuando el juego te muestra la misión."] = "A história é guardada quando o jogo mostra a missão.",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "A fonte do tema (Inter no do Alfa, Fira Sans no Halo, a do jogo nos outros) ou a que você escolher.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "A lista está desativada: ative “Sua lista de sons” em Comodidades (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "A lista por nível e seu progresso.",
	["La lupa de la cabecera del rastreador abre el menú. También: /alfa cerca o tu tecla."] = "A lupa no cabeçalho do rastreador abre o menu. Também: /alfa cerca ou sua tecla.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "A linha do tempo da Blizzard diz qual ataque vem e quando, e as mensagens grandes, o que é perigoso. O Alfa não inventa avisos: você ativa e ajusta em Opções.",
	["La línea del camino también en el minimapa."] = "A linha do caminho também no minimapa.",
	["La manada a la vista"] = "A matilha à vista",
	["La manada aúlla contigo."] = "A matilha uiva com você.",
	["La manada es fuerte porque cada lobo lo es. Y tú lo eres."] = "A matilha é forte porque cada lobo é. E você é.",
	["La manada no te ve en el mapa"] = "A matilha não vê você no mapa",
	["La manada no ve a tu personaje en el mapa."] = "A matilha não vê seu personagem no mapa.",
	["La manada te ve en el mapa"] = "A matilha vê você no mapa",
	["La manada te ve en el mapa: %s"] = "A matilha vê você no mapa: %s",
	["La manada ya no ve a tu personaje en el mapa."] = "A matilha não vê mais seu personagem no mapa.",
	["La manada ya ve a tu personaje en el mapa del juego."] = "A matilha agora vê seu personagem no mapa do jogo.",
	["La manada ya ve a tu personaje en el mapa del juego. Lo cambias cuando quieras en /alfa manada."] = "A matilha agora vê seu personagem no mapa do jogo. Mude quando quiser com /alfa manada.",
	["La mazmorra"] = "A masmorra",
	["La mazmorra para mi nivel"] = "A masmorra para o meu nível",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "A masmorra para o seu nível, seus chefes, saque, missões e dicas.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "A masmorra para o seu nível, as missões dela e como chegar.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "A masmorra para o seu nível; com um nome, essa masmorra (também: progreso, ajustes)",
	["La mezcla de texturas del terreno."] = "A mistura de texturas do terreno.",
	["La misión"] = "A missão",
	["La montura"] = "A montaria",
	["La niebla con cuerpo de valles, pantanos y amaneceres."] = "A neblina densa de vales, pântanos e amanheceres.",
	["La pantalla se pone negra uno o dos segundos mientras el juego vuelve a arrancar los gráficos. No sales del juego ni pierdes nada."] = "A tela fica preta por um ou dois segundos enquanto o jogo reinicia os gráficos. Você não sai do jogo nem perde nada.",
	["La pesca de Alfa está apagada"] = "A pesca do Alfa está desativada",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "A precisão é o mais importante: com duas armas você erra muito sem ela.",
	["La primera vez: %s%s."] = "A primeira vez: %s%s.",
	["La profesión"] = "A profissão",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "A página de Bolsas; “abrir” abre suas bolsas e “banco”, o seu banco",
	["La que te toca, con sus misiones y su botín."] = "A certa para você, com suas missões e seu saque.",
	["La recoges ahora"] = "Você pega agora",
	["La recomendada para ti y todas las demás"] = "O recomendado para você e todos os outros",
	["La recomendada para ti y todas las demás."] = "O recomendado para você e todos os outros.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "A rota mais rápida a partir do seu nível, missão por missão.",
	["La ruta no trae tramos."] = "A rota não tem trechos.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "A rota leva você até %s. A seta está desativada: ative em Opções > Guia para vê-la.",
	["La sabes"] = "Você sabe",
	["La sacas de tu plan."] = "Você a tira do seu plano.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "O próximo espaço custa %s e ainda não dá para pagar.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "O leilão permite escanear tudo a cada 15 minutos. Falta %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "O leilão não aceitou o escaneamento. Tente de novo mais tarde.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "O leilão não enviou nenhum leilão. Tente de novo mais tarde.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "O leilão não respondeu. Talvez ainda esteja em espera: tente em alguns minutos.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "A soma do que o Alfa guardou de cada personagem (o seu, atualizado).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "A tecla do botão da sua barra com essa habilidade, sobre o ícone.",
	["La tecla del mapa abre este mapa"] = "A tecla do mapa abre este mapa",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "A tecla que abre o mapa do jogo (M) abre o do Alfa; nele, um botão leva você ao do jogo. Desative e a tecla volta a abrir o do jogo. Você também pode dar a ele uma tecla própria em Opções > Atalhos > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "A tecla que você usava no seu outro addon de pesca (%s) agora pesca com o Alfa.",
	["La tomo otra vez"] = "Vou pegar de novo",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "O retalhador derruba as pessoas: chame a atenção dele de novo rápido.",
	["La tuya tiene %d semanas: salen seguido."] = "A sua tem %d semanas: saem versões com frequência.",
	["La venta se detuvo: vendiste %d de %d."] = "A venda parou: você vendeu %d de %d.",
	["La ventana"] = "A janela",
	["La ventana del Legado no abrió."] = "A janela do Legado não abriu.",
	["La última: %s."] = "A última: %s.",
	["Lady Sylvanas Brisaveloz gobierna a los Renegados. Fue general forestal de Quel'Thalas antes de que Arthas la matara."] = "Lady Sylvanas Correventos governa os Renegados. Foi General Patrulheira de Quel'Thalas antes que Arthas a matasse.",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Ele lança bolas de fogo e fogo ao redor: interrompa e, se você luta à distância, afaste-se.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Ele joga bombas de fumaça que atordoam: saia da fumaça.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Ele lança trepadeiras que derrubam todos que estão perto: se você luta à distância, fique longe.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Ele lança fogo ao redor: se você luta à distância, afaste-se dele.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Ele lança feitiços de terra e coloca totens: quebrem os totens primeiro.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Ele lança metal derretido: se você não for o tanque, não fique colado nele.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Ela lança raios e pode se curar: interrompa os feitiços dela.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Ele lança rajadas arcanas: interrompa.",
	["Lanza sombras: interrúmpelo."] = "Ele lança sombras: interrompa.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Ele lança teias e uma maldição: remova a maldição se puder.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Ele lança tempestades de areia que se movem pela sala: não fique parado nelas.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Lance seu feitiço mais forte de longe e acabe com os instantâneos.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Lance seu feitiço mais forte primeiro e acabe com um choque.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Ela solta uma nuvem de veneno para a frente: vire-a para longe do grupo.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Ele lança uma rede que deixa um jogador parado: não é grave, continue atacando.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Ele lança veneno em todos: remova o veneno se puder.",
	["Lanzado"] = "Lançado",
	["Lanzamientos"] = "Lançamentos",
	["Lanzamientos: %d de %d"] = "Lançamentos: %d de %d",
	["Las Estepas Ardientes se incendiaron cuando Ragnaros despertó, y sus brasas siguen sin apagarse."] = "As Estepes Ardentes pegaram fogo quando Ragnaros despertou, e suas brasas continuam sem se apagar.",
	["Las Islas del Eco eran el hogar de los Lanza Negra, hasta que el brujo Zalazane sometió a muchos con su vudú y los demás tuvieron que mudarse a tierra firme."] = "As Ilhas do Eco eram o lar dos Lançanegra, até que o feiticeiro Zalazane subjugou muitos com seu vodu e os demais tiveram que se mudar para o continente.",
	["Las Minas de la Muerte esconden el refugio de VanCleef... y hasta un barco pirata."] = "As Minas Mortas escondem o refúgio de VanCleef... e até um navio pirata.",
	["Las aguas de nivel 20 a 35. El rango Experto se aprende con el libro que vende el pescador de Bahía del Botín."] = "As águas de nível 20 a 35. A faixa Especialista se aprende com o livro que o pescador de Angra do Butim vende.",
	["Las barras de abajo"] = "As barras de baixo",
	["Las centinelas de Vallefresno pelean sin descanso contra los leñadores orcos de Grito de Guerra."] = "As sentinelas do Vale Gris lutam sem descanso contra os lenhadores orcs Brado Guerreiro.",
	["Las centinelas domestican sables de hielo en Cuna del Invierno, y se los confían solo a quien se gana su respeto."] = "As sentinelas domesticam sabres-gélidos em Hibérnia e só os confiam a quem conquista seu respeito.",
	["Las criaturas que invocan los enemigos por un rato."] = "As criaturas que os inimigos invocam por um tempo.",
	["Las cuentas"] = "As contas",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "As contas de teste não podem compartilhar: o jogo não permite.",
	["Las demás"] = "As demais",
	["Las demás ranuras"] = "Os demais espaços",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "As duas sobem sozinhas enquanto você mata e viaja, e o que você junta vende bem: ouro para sua montaria e suas habilidades.",
	["Las esquinas de la pantalla se oscurecen poco a poco, como en una foto."] = "Os cantos da tela escurecem aos poucos, como numa foto.",
	["Las excavaciones de los enanos despertaron a los troggs, y ahora Thelsamar tiene que cuidarse de ellos."] = "As escavações dos anões despertaram os troggs, e agora Thelsamar precisa se cuidar deles.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "As linhas que Anunciar escreve no chat do seu grupo ou raide.",
	["Las marca con una flecha."] = "As melhorias ganham uma seta.",
	["Las marcas de la manada también en el minimapa, no solo en el mapa del mundo."] = "As marcas da matilha também no minimapa, não só no mapa-múndi.",
	["Las marcas en el suelo de hechizos y áreas. Apagarlas esconde avisos de combate: mejor dejarlas encendidas."] = "As marcas no chão de feitiços e áreas. Desligá-las esconde avisos de combate: melhor deixá-las ligadas.",
	["Las mejores misiones que ya puedes tomar cerca de ti, en el orden más corto."] = "As melhores missões que você já pode pegar perto de você, na ordem mais curta.",
	["Las mesetas de Cima del Trueno están unidas por puentes, y a la ciudad se sube en elevadores."] = "Os planaltos do Penhasco do Trovão são unidos por pontes, e se sobe à cidade por elevadores.",
	["Las metas se cumplen solas al hacerlas; las notas las marcas tú. Ordénalas como quieras."] = "As metas se cumprem sozinhas quando você as faz; as notas você marca. Ordene como quiser.",
	["Las misiones grises dan poca XP. Entrégalas y sigue adelante."] = "As missões cinzas dão pouca XP. Entregue e siga em frente.",
	["Las misiones previas y el nivel que pide, para poder tomarla."] = "As missões anteriores e o nível que pede, para poder pegá-la.",
	["Las misiones que más experiencia dan cerca de ti."] = "As missões que dão mais experiência perto de você.",
	["Las monturas de otra raza de tu bando pueden pedir reputación con su ciudad: la de tu raza siempre se puede."] = "As montarias de outra raça da sua facção podem pedir reputação com a cidade dela: as da sua raça sempre estão disponíveis.",
	["Las monturas de tu raza"] = "As montarias da sua raça",
	["Las ondas al caminar o nadar en el agua."] = "As ondulações ao andar ou nadar na água.",
	["Las orillas de la pantalla un poco más oscuras."] = "As bordas da tela um pouco mais escuras.",
	["Las pestañas toman la letra y los colores del estilo; la elegida lleva la línea de acento. En Clásico WoW quedan las del juego."] = "As abas assumem a fonte e as cores do estilo; a escolhida leva a linha de destaque. No WoW Clássico ficam as do jogo.",
	["Las placas de nombre de los enemigos."] = "As placas de nome dos inimigos.",
	["Las plantas de herboristería."] = "As plantas de herborismo.",
	["Las profesiones de recolección dan oro desde el nivel 1. ¡Hierbas o minería!"] = "As profissões de coleta dão ouro desde o nível 1. Herborismo ou mineração!",
	["Las que me faltan"] = "As que me faltam",
	["Las que se hacen una sola vez."] = "As que se fazem uma vez só.",
	["Las que se repiten cada día."] = "As que se repetem todo dia.",
	["Las que se repiten cada semana."] = "As que se repetem toda semana.",
	["Las que tengo"] = "As que tenho",
	["Las que vienen después, más pequeñas a la derecha."] = "As que vêm depois, menores, à direita.",
	["Las que ya hiciste no cuentan."] = "As que você já fez não contam.",
	["Las rutas y los planes que armas en la página Ruta de Alfa."] = "As rotas e os planos que você monta na página Rota do Alfa.",
	["Las sesiones guardadas de este personaje."] = "As sessões salvas deste personagem.",
	["Las sesiones, las zonas y los objetos de este personaje."] = "As sessões, as zonas e os itens deste personagem.",
	["Las ventanas de chat, sus pestañas y la caja para escribir toman el estilo que elijas abajo y cambian con él. Al apagarlo vuelve el chat de siempre, sin /reload."] = "As janelas de chat, suas abas e a caixa de texto assumem o estilo que você escolher abaixo e mudam com ele. Ao desligar, volta o chat de sempre, sem /reload.",
	["Lavanda"] = "Lavanda",
