	["Listo: tu mapa también funciona en los marcos de Blizzard."] = "Pronto: o seu mapa também funciona nos quadros da Blizzard.",
	["Llama a varios lobos al empezar: usen ataques en área o maten primero a los lobos."] = "Ele chama vários lobos no começo: usem ataques em área ou matem os lobos primeiro.",
