	["Llega con su perro: una persona debe tanquear a cada uno, o maten al perro primero."] = "Ele chega com o cachorro: uma pessoa deve tanquear cada um, ou matem o cachorro primeiro.",
	["Llega en el nivel %d"] = "Chega no nível %d",
	["Llegar a nivel %d"] = "Chegar ao nível %d",
