	["Llegaste al final; quedaron %d pasos sin hacer."] = "Você chegou ao fim; ficaram %d passos sem fazer.",
	["Llegaste con %s."] = "Você chegou até %s.",
	["Lleva al máximo la distancia de la cámara (la de Opciones > Controles). Al apagarlo vuelve la que tenías."] = "Leva a distância da câmera ao máximo (a de Opções > Controles). Ao desativar, volta a que você tinha.",
	["Lleva siempre un sello puesto aunque estés curando."] = "Mantenha sempre um selo ativo, mesmo curando.",
	["Lleva siempre vendas y comida: descansar poco y seguro es más rápido que morir."] = "Leve sempre ataduras e comida: descansar pouco e com segurança é mais rápido do que morrer.",
	["Llevarla a Mis planes"] = "Levar para Meus planos",
	["Llevas %d de %d pasos. El rastreador te dice el siguiente y la flecha te lleva."] = "Você está no passo %d de %d. O rastreador diz o próximo e a seta leva você.",
