	["Llevas %s jugando. Estírate, toma agua y regresas con más fuerza."] = "Você está jogando há %s. Alongue-se, beba água e volte com mais força.",
	["Llevas %s. La manada te espera aunque te tomes un respiro."] = "Já faz %s. A matilha espera por você mesmo que você dê uma pausa.",
	["Llevas %s. Si cierras sesión en una posada, ganas XP descansada."] = "Já faz %s. Se você sair do jogo em uma estalagem, ganha XP de descanso.",
