	["Lo conozco de memoria"] = "Conheço de cor",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "Entre %s e %s tem toda uma história. Quer ouvir?",
	["Lo demás, de un vistazo"] = "O resto, num relance",
