	["Lo estás siguiendo."] = "Você está seguindo.",
	["Lo gris y lo que marcaste como chatarra. Nunca lo que marcaste para conservar ni lo que pide una misión."] = "O cinza e o que você marcou como lixo. Nunca o que você marcou para guardar nem o que uma missão pede.",
