	["Oculta lo que tu clase no puede usar o no le conviene: armadura de otro tipo, armas que no usas, piezas sin nada para tu especialización."] = "Esconde o que a sua classe não pode usar ou não vale a pena: armadura de outro tipo, armas que você não usa, peças sem nada para a sua especialização.",
