	["Para cada objeto Alfa compara tres caminos: venderlo al comerciante, ponerlo en la subasta o transformarlo (con una receta que conoces o desencantándolo)."] = "Para cada item, o Alfa compara três caminhos: vender ao mercador, pôr no leilão ou transformar (com uma receita que você conhece ou desencantando).",
