	["Para mi nivel (±3)"] = "Para o meu nível (±3)",
	["Para mí"] = "Para mim",
	["Para no chocar con él, Alfa no reemplaza tus bolsas mientras esté activo. Igual puedes abrir la ventana de Alfa desde aquí."] = "Para não conflitar com ele, o Alfa não substitui suas bolsas enquanto ele estiver ativo. Mesmo assim, você pode abrir a janela do Alfa por aqui.",
	["Para no moverla sin querer. Sin bloquear, arrástrala a donde quieras."] = "Para não movê-la sem querer. Destravada, arraste-a para onde quiser.",
	["Para no ver dos veces a tu grupo. Se cambia fuera de combate."] = "Para não ver seu grupo duas vezes. Muda fora de combate.",
	["Para que no choquen, Alfa no toma tu tecla ni cambia tus ajustes. Desactiva uno de los dos en la lista de addons (pantalla de personajes) y recarga. Si dejas Alfa, tomará sola la tecla que usabas en el otro addon."] = "Para eles não entrarem em conflito, o Alfa não pega sua tecla nem muda suas opções. Desative um dos dois na lista de addons (tela de personagens) e recarregue. Se ficar com o Alfa, ele vai pegar sozinho a tecla que você usava no outro addon.",
	["Para que no dejes botín tirado por falta de espacio."] = "Para você não deixar saque para trás por falta de espaço.",
	["Para quien prefiere seleccionar con el izquierdo: la cura de ese clic pasa al botón central. Se vuelve a aplicar tu preajuste."] = "Para quem prefere selecionar com o esquerdo: a cura desse clique passa para o botão do meio. A sua predefinição é aplicada de novo.",
