	["Sobre tu compañero, este clic %s."] = "No seu companheiro, este clique %s.",
	["Solo"] = "Sozinho",
	["Solo %s"] = "Só %s",
	["Solo al acabarse"] = "Só quando acabar",
	["Solo al moverte"] = "Só ao se mover",
	["Solo buffs"] = "Só buffs",
	["Solo con quienes usan Alfa y aceptaron compartir. Tú decides."] = "Só com quem usa o Alfa e aceitou compartilhar. Você decide.",
	["Solo cuando estás en grupo"] = "Só quando você está em grupo",
	["Solo el botín que me sirve"] = "Só o saque que me serve",
	["Solo en una fiesta del año"] = "Só durante um evento do ano",
	["Solo en warcraft.wiki.gg e Icy Veins: cuántos puntos pide cada premio (15, 25, 40 y 55). Ninguna fuente publica cuánto cuesta cada rango de los árboles: míralo en la ventana del Legado."] = "Só em warcraft.wiki.gg e Icy Veins: quantos pontos cada prêmio pede (15, 25, 40 e 55). Nenhuma fonte publica quanto custa cada nível das árvores: veja na janela do Legado.",
	["Solo encontré %d misiones que te sirvan ahora."] = "Só encontrei %d missões que servem para você agora.",
	["Solo importantes"] = "Só importantes",
	["Solo la entrada"] = "Só a entrada",
	["Solo las misiones de tu ruta"] = "Só as missões da sua rota",
	["Solo las que puedes tomar: tu bando, raza, clase y nivel, y que no hayas hecho."] = "Só as que você pode pegar: sua facção, raça, classe e nível, e que você ainda não fez.",
	["Solo lo de mi papel"] = "Só o da minha função",
	["Solo lo que tu clase puede usar y le conviene a tu especialización."] = "Só o que sua classe pode usar e convém à sua especialização.",
	["Solo lo que tu personaje puede usar hoy: clase, armadura, armas, nivel y profesión."] = "Só o que seu personagem pode usar hoje: classe, armadura, armas, nível e profissão.",
	["Solo lo que ya puedes recolectar"] = "Só o que você já pode coletar",
	["Solo los de la zona donde estás."] = "Só os da zona onde você está.",
	["Solo los de tus profesiones, en el mapa del mundo y en el minimapa."] = "Só os das suas profissões, no mapa-múndi e no minimapa.",
	["Solo los graves"] = "Só os graves",
	["Solo los que me apuntan a mí"] = "Só os que miram em mim",
	["Solo misiones de XP, las mejores cerca de ti, en tres tandas."] = "Só missões de XP, as melhores perto de você, em três levas.",
	["Solo para %s."] = "Só para %s.",
	["Solo puedes tener dos principales a la vez; las secundarias son libres. Se aprenden con su entrenador en las ciudades."] = "Você só pode ter duas principais ao mesmo tempo; as secundárias são livres. Elas se aprendem com o instrutor nas cidades.",
	["Solo se admite la versión 1 de la cadena de escala."] = "Só a versão 1 do código de escala é suportada.",
	["Solo si falta"] = "Só se faltar",
	["Solo si le pido"] = "Só se eu pedir",
	["Solo sirve con un monitor HDR y el HDR de Windows encendido (Configuración > Pantalla). Sin eso, déjalo apagado: los colores se ven lavados."] = "Só funciona com um monitor HDR e o HDR do Windows ligado (Configurações > Tela). Sem isso, deixe desligado: as cores ficam desbotadas.",
	["Solo tocan gráficos: nunca la cámara, el ratón ni la interfaz. «Deshacer» devuelve lo que tenías antes del último que aplicaste."] = "Só mexem nos gráficos: nunca na câmera, no mouse nem na interface. «Desfazer» devolve o que você tinha antes da última que aplicou.",
	["Solo tu grupo y quienes usan Alfa y aceptaron compartir."] = "Só seu grupo e quem usa o Alfa e aceitou compartilhar.",
	["Solo tú"] = "Só você",
	["Solo tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Só você, seu grupo, seus marcadores e o próximo passo do guia.",
	["Sombra"] = "Sombra",
	["Sombra para subir"] = "Sombra para subir de nível",
	["Sombra suave en rincones, pliegues y bajo los objetos: da volumen a todo."] = "Sombra suave em cantos, dobras e sob os objetos: dá volume a tudo.",
	["Sombras"] = "Sombras",
	["Sombras con bordes más finos. Usa más memoria de video."] = "Sombras com bordas mais finas. Usa mais memória de vídeo.",
	["Sombras suaves"] = "Sombras suaves",
	["Son %s más que venderlo todo al comerciante."] = "São %s a mais do que vender tudo ao mercador.",
	["Son puntos de tu cuenta: los ganas con los retos del Legado (logros de Forever) en cualquier personaje, y cada personaje los gasta por su cuenta en sus árboles."] = "São pontos da sua conta: você os ganha com os desafios do Legado (conquistas do Forever) em qualquer personagem, e cada personagem os gasta por conta própria nas suas árvores.",
	["Son tres enanos que pelean juntos: uno dispara de lejos, otro es muy veloz y otro se protege con escudo. Mátenlos uno por uno."] = "São três anões que lutam juntos: um atira de longe, outro é muito rápido e outro se protege com escudo. Matem um de cada vez.",
	["Sonido"] = "Som",
	["Sonido con el juego en segundo plano"] = "Som com o jogo em segundo plano",
	["Sonido de los avisos"] = "Som dos avisos",
	["Sonido en los avisos urgentes"] = "Som nos avisos urgentes",
	["Sonido suave"] = "Som suave",
