	["Sonidos suaves del juego: nada de voces ni sonidos repetidos."] = "Sons suaves do jogo: nada de vozes nem sons repetidos.",
	["Sorpresa"] = "Surpresa",
	["Sorpresas y cofres"] = "Surpresas e baús",
	["Stromgarde, la heredera de Strom, resiste a medias: trols, ogros y el Sindicato se pelean por sus ruinas."] = "Stromgarde, a herdeira de Strom, resiste a duras penas: trolls, ogros e o Sindicato brigam por suas ruínas.",
	["Su arpón envenena: quita el veneno si puedes."] = "O arpão dele envenena: remova o veneno se puder.",
	["Su botín está por descubrir"] = "O saque dele ainda está por descobrir",
	["Su electricidad salta de un jugador a otro: sepárense."] = "A eletricidade dele pula de um jogador para outro: espalhem-se.",
	["Su final no alcanzó a guardarse."] = "O final dela não chegou a ser guardado.",
	["Su mordida envenena: quita el veneno si puedes."] = "A mordida dele envenena: remova o veneno se puder.",
	["Su oro y sus recompensas ya son tuyos: solo falta entregarlas."] = "O ouro e as recompensas delas já são seus: só falta entregar.",
	["Su rayo salta de un jugador a otro: no se queden todos juntos."] = "O raio dele pula de um jogador para outro: não fiquem todos juntos.",
	["Su rayo salta de un jugador a otro: sepárense un poco."] = "O raio dele pula de um jogador para outro: espalhem-se um pouco.",
	["Suave"] = "Suave",
