	["Subastar"] = "Leiloar",
	["Subastar %d"] = "Leiloar %d",
	["Sube los efectos y baja la música y el ambiente para que oigas el chapoteo. Al terminar, todo vuelve a como estaba."] = "Aumenta os efeitos e abaixa a música e o ambiente para você ouvir o espirro d'água. Ao terminar, tudo volta a ser como era.",
	["Sube tu profesión o junta sus materiales donde más hay."] = "Suba sua profissão ou junte os materiais dela onde há mais.",
	["Sube tus oficios con lo que tienes cerca."] = "Suba suas profissões com o que há por perto.",
	["Subidón de adrenalina: recuperas energía mucho más rápido."] = "Adrenalina: você recupera energia muito mais rápido.",
	["Subir"] = "Subir",
	["Subir %s a %d"] = "Subir %s até %d",
	["Subir cocina y pesca juntas"] = "Subir culinária e pesca juntas",
	["Subir como tanque: más lento que Armas, pero casi nunca mueres, juntas varios monstruos a la vez y llegas listo para tanquear cualquier mazmorra."] = "Subir como tanque: mais lento que Armas, mas você quase nunca morre, junta vários monstros de uma vez e chega pronto para tanquear qualquer masmorra.",
	["Subir de nivel"] = "Subir de nível",
	["Subir de nivel, profesiones, hacer oro o mazmorras: dos clics y Alfa te lleva."] = "Subir de nível, profissões, fazer ouro ou masmorras: dois cliques e o Alfa leva você.",
