	["Teldrassil es un árbol del mundo que los elfos de la noche plantaron sin la bendición de los dragones. Por eso no les dio la inmortalidad."] = "Teldrassil é uma árvore do mundo que os elfos noturnos plantaram sem a bênção dos dragões. Por isso não lhes deu a imortalidade.",
