	["Terreno, como el minimapa"] = "Terreno, como o minimapa",
	["Terreno: al acercarte se ve el suelo real del minimapa, con sus montañas, ríos y tonos. Clásico: solo el mapa pintado del juego."] = "Terreno: ao aproximar, aparece o chão real do minimapa, com montanhas, rios e tons. Clássico: só o mapa pintado do jogo.",
