	["Tiempo pescando"] = "Tempo pescando",
	["Tiene cuatro partes que se hacen por separado: Cementerio, Biblioteca, Armería y Catedral, de la más fácil a la más difícil."] = "Tem quatro partes que se fazem separadas: Cemitério, Biblioteca, Arsenal e Catedral, da mais fácil para a mais difícil.",
