	["Tienes %d encendidas. Abajo está cada una, con lo que hace, por si quieres cambiar algo."] = "Você tem %d ativadas. Abaixo está cada uma, com o que faz, caso queira mudar algo.",
	["Tienes %d misiones listas para entregar"] = "Você tem %d missões prontas para entregar",
