	["Tienes %s de %s"] = "Você tem %s de %s",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Você tem %s preços das suas buscas. Para conhecer todos, escaneie na casa de leilões.",
	["Tienes 1 misión lista para entregar"] = "Você tem 1 missão pronta para entregar",
