	["Tienes cambios sin confirmar en la ventana de talentos: se descartan antes de aplicar."] = "Você tem mudanças não confirmadas na janela de talentos: elas são descartadas antes de aplicar.",
	["Tienes encendido «solo las misiones de mi ruta»: solo acepta las de tu ruta."] = "Você tem ativado “Só as da minha rota”: só aceita as missões da sua rota.",
