	["Todavía no tienes marcadores"] = "Você ainda não tem marcadores",
	["Todavía no tienes rutas propias"] = "Você ainda não tem rotas próprias",
	["Todavía no tienes talentos para compartir."] = "Você ainda não tem talentos para compartilhar.",
	["Todavía no tienes una guía abierta. Elige una y Alfa te lleva paso a paso: a dónde ir, qué hacer y con quién hablar."] = "Você ainda não tem um guia aberto. Escolha um e o Alfa leva você passo a passo: aonde ir, o que fazer e com quem falar.",
	["Todavía quedan pilones de los titanes en el cráter, y funcionan con cristales de colores."] = "Ainda restam pilares dos titãs na cratera, e funcionam com cristais coloridos.",
	["Todo"] = "Tudo",
	["Todo Azeroth en un solo lienzo: acerca con la rueda, arrastra para moverte y pon tus marcadores con clic derecho."] = "Toda Azeroth numa só tela: aproxime com a roda, arraste para se mover e coloque seus marcadores com clique direito.",
	["Todo al máximo seguro. Pide una tarjeta de video fuerte."] = "Tudo no máximo seguro. Pede uma placa de vídeo forte.",
	["Todo bien (lo más gastado: %d%%)"] = "Tudo certo (o mais desgastado: %d%%)",
	["Todo como estaba antes de Alfa"] = "Tudo como era antes do Alfa",
	["Todo con tu estilo"] = "Tudo no seu estilo",
	["Todo el juego, aunque no lo tengas"] = "O jogo inteiro, mesmo o que você não tem",
	["Todo el juego, aunque no lo tengas: objetos, PNJ, misiones, zonas y raros."] = "O jogo inteiro, mesmo o que você não tem: itens, PNJs, missões, zonas e raros.",
	["Todo el juego, aunque no lo tengas: objetos, monturas, mascotas, PNJ, misiones, zonas y raros."] = "O jogo inteiro, mesmo o que você não tem: itens, montarias, mascotes, PNJs, missões, zonas e raros.",
	["Todo en orden"] = "Tudo em ordem",
	["Todo esto lo hace Alfa sola al hablar con quien da o recibe una misión. Mantén presionado Mayús para hacerlo tú en el momento."] = "O Alfa faz tudo isso sozinho quando você fala com quem dá ou recebe uma missão. Segure Shift para fazer você mesmo na hora.",
	["Todo junto"] = "Tudo junto",
	["Todo junto muestra cada casilla en su lugar; por categorías agrupa equipo, consumibles, misiones y materiales; por bolsa pone cada bolsa en su bloque."] = "Tudo junto mostra cada espaço no seu lugar; por categoria agrupa equipamento, consumíveis, missões e materiais; por bolsa coloca cada bolsa no seu bloco.",
	["Todo listo"] = "Tudo pronto",
	["Todo lo que no sea equipo"] = "Tudo o que não for equipamento",
	["Todo lo que se pinta en tus mapas, en un solo lugar. Lo de otros módulos de Alfa también llega aquí."] = "Tudo o que aparece nos seus mapas, num só lugar. O que vem de outros módulos do Alfa também chega aqui.",
	["Todo nivel"] = "Qualquer nível",
	["Todo objeto, PNJ, misión, zona y raro, con dónde conseguirlo y «Guíame»."] = "Todo item, PNJ, missão, zona e raro, com onde conseguir e “Me guie”.",
	["Todo oficio"] = "Qualquer função",
	["Todo para el daño: críticos, sangrados y Abrumar muy seguido. Matas rapidísimo, pero no hay defensa extra: si se te juntan muchos, corre."] = "Tudo pelo dano: críticos, sangramentos e Sobrepujar com muita frequência. Você mata rapidíssimo, mas não há defesa extra: se muitos se juntarem contra você, corra.",
	["Todo subtipo"] = "Qualquer subtipo",
	["Todo tipo"] = "Qualquer tipo",
	["Todos"] = "Todos",
	["Todos llegan a %s"] = "Todos levam a %s",
	["Todos los de ese tipo, o solo uno (por ejemplo, solo cobre). Entre paréntesis, cuántos hay en tu zona."] = "Todos desse tipo, ou só um (por exemplo, só cobre). Entre parênteses, quantos há na sua zona.",
	["Todos los materiales"] = "Todos os materiais",
	["Todos los niveles"] = "Todos os níveis",
	["Todos los objetos, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Todos os itens, PNJs, missões, zonas e raros, mesmo os que você não tem: quem deixa cair e com que chance, quem vende e onde, que missão dá e como chegar.",
	["Todos los objetos, monturas, mascotas, PNJ, misiones, zonas y raros, aunque no los tengas: quién lo suelta y con qué probabilidad, quién lo vende y dónde, qué misión lo da y cómo llegar."] = "Todos os itens, montarias, mascotes, PNJs, missões, zonas e raros, mesmo que você não os tenha: quem derruba e com que chance, quem vende e onde, que missão dá e como chegar.",
	["Todos los pasos"] = "Todos os passos",
	["Todos los pasos de esta guía; clic en uno para verlo."] = "Todos os passos deste guia; clique em um para vê-lo.",
	["Todos los pasos de la guía en la ventana de guía."] = "Todos os passos do guia, na janela do guia.",
	["Todos los tipos"] = "Todos os tipos",
	["Todos tus puntos ya están gastados y parte de ellos fuera de este build. Para cambiarte a este build, reinicia tus talentos con tu entrenador de clase; después Alfa te los aplica con un clic."] = "Todos os seus pontos já estão gastos, e parte deles fora desta build. Para mudar para esta build, redefina seus talentos com o seu instrutor de classe; depois o Alfa aplica tudo com um clique.",
	["Todos: también los avisos leves. Solo los graves: únicamente lo que puede matarte."] = "Todos: também os avisos leves. Só os graves: apenas o que pode matar você.",
	["Toma el botín de la pesca enseguida, aunque tengas apagado el botín automático del juego."] = "Pega o saque da pesca na hora, mesmo com o saque automático do jogo desativado.",
	["Toma las de tu ruta que tienes cerca"] = "Pegue as da sua rota que estão perto",
	["Toma las mejores de cerca que ya puedes hacer."] = "Pegue as melhores por perto que você já pode fazer.",
	["Toma las mejores misiones de por aquí y después ciérralas juntas."] = "Pegue as melhores missões daqui e depois feche-as juntas.",
	["Toma todo el botín de una vez cuando tienes el despojo automático."] = "Pega todo o saque de uma vez quando o saque automático está ligado.",
	["Toma unas misiones cerca y Alfa las cierra contigo por el camino más corto."] = "Pegue umas missões por perto e o Alfa fecha-as com você pelo caminho mais curto.",
	["Tomar %s"] = "Pegar %s",
	["Tomar el vuelo de tu ruta"] = "Pegar o voo da sua rota",
	["Tomar la mejor recompensa"] = "Pegar a melhor recompensa",
	["Tomarla"] = "Pegá-la",
