	["Tomaste otra misión de su grupo: esta ya no se abre."] = "Você pegou outra missão do grupo dela: esta não abre mais.",
	["Top %d de %s"] = "Top %d de %s",
	["Top de daño"] = "Top de dano",
	["Tope por personaje"] = "Limite por personagem",
	["Tortura mental: daño constante y frena al enemigo."] = "Açoite Mental: dano constante e deixa o inimigo mais lento.",
	["Total"] = "Total",
	["Tramo %d de %d: %s."] = "Trecho %d de %d: %s.",
	["Trampas, golpes cuerpo a cuerpo de emergencia y mucha agilidad: el cazador más difícil de atrapar."] = "Armadilhas, golpes corpo a corpo de emergência e muita agilidade: o caçador mais difícil de pegar.",
	["Tranquilo"] = "Tranquilo",
	["Transformar"] = "Transformar",
	["Transformar %d"] = "Transformar %d",
	["Tras aceptar o entregar, cierra la ventana del PNJ si solo ofrece misiones que tu guía no hace."] = "Depois de aceitar ou entregar, fecha a janela do PNJ se ele só oferece missões que seu guia não faz.",
	["Tratado"] = "Libram",
	["Tres caminos para cada objeto"] = "Três caminhos para cada item",
