	["Trilineal"] = "Trilinear",
	["Trinquete es un puerto goblin neutral: ahí se tolera a cualquiera que traiga oro, y su barco lleva hasta Bahía del Botín."] = "Vila Catraca é um porto goblin neutro: ali se tolera qualquer um que traga ouro, e seu barco vai até Angra do Butim.",
