	["Tu especialización"] = "Sua especialização",
	["Tu estilo"] = "Seu estilo",
	["Tu estilo (Alfa, Clásico WoW o Cristal), el color de acento y el aullido."] = "Seu estilo (Alfa, WoW Clássico ou Cristal), a cor de destaque e o uivo.",
