	["Tu nivel, reparar, comida y bebida, y la entrada de la mazmorra para ti."] = "Seu nível, reparos, comida e bebida, e a entrada da masmorra para você.",
	["Tu nota"] = "Sua nota",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Seu alvo se esquivou: Sobrepujar não pode ser esquivado e bate forte. Precisa da Postura de Batalha.",
	["Tu oro"] = "Seu ouro",
	["Tu personaje"] = "Seu personagem",
	["Tu personaje aparece en el mapa de quienes también se dejan ver. Solo su lugar en el juego, nunca dentro de mazmorras ni por canales públicos."] = "Seu personagem aparece no mapa de quem também se deixa ver. Só o lugar dele no jogo, nunca dentro de masmorras nem por canais públicos.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Seu personagem para de dizer \"Mana insuficiente\", \"Ainda não está pronto\" e coisas parecidas. O texto vermelho continua.",
	["Tu personaje no aparece en el mapa de nadie de La Jauría. Lo cambias cuando quieras en la página de La Jauría."] = "Seu personagem não aparece no mapa de ninguém de La Jauría. Mude quando quiser na página de La Jauría.",
