	["Tu progreso"] = "Seu progresso",
	["Tu propia lista de metas, en el orden que quieras: un objeto, oro, una profesión, un lugar, una misión, un nivel o una nota. Alfa las mide solas y te lleva a cada una."] = "Sua própria lista de metas, na ordem que você quiser: um item, ouro, uma profissão, um lugar, uma missão, um nível ou uma nota. O Alfa as mede sozinho e leva você a cada uma.",
