	["Tu último escaneo fue %s. Escanea otra vez en la casa de subastas para tener precios al día."] = "Seu último escaneamento foi %s. Escaneie de novo na casa de leilões para ter preços atualizados.",
	["Tus %d puntos están donde tu build los pide. Lo que sigue es el equipo: piezas con las estadísticas que le sirven a tu build."] = "Seus %d pontos estão onde sua build pede. O próximo é o equipamento: peças com os atributos que servem para sua build.",
	["Tus avisos"] = "Seus avisos",
	["Tus bolsas"] = "Suas bolsas",
