	["Tus clics vuelven a los del preajuste. Lo que cambiaste a mano se pierde."] = "Seus cliques voltam aos da predefinição. O que você mudou à mão se perde.",
	["Tus comodidades están listas"] = "Suas comodidades estão prontas",
	["Tus compañeros de grupo y de banda en el mapa de Alfa."] = "Seus companheiros de grupo e de raide no mapa do Alfa.",
	["Tus críticos de habilidades pegan todavía más."] = "Seus críticos de habilidades batem ainda mais.",
	["Tus críticos hacen muchísimo daño."] = "Seus críticos causam muitíssimo dano.",
