	["Tus flechas de mejora usan tu build"] = "Suas setas de melhoria usam sua build",
	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Seus golpes alcançam um segundo inimigo: perfeito quando dois se juntam contra você.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Seus brados alcançam mais longe e duram mais: você ajuda o grupo todo.",
	["Tus habilidades cuestan menos ira."] = "Suas habilidades custam menos raiva.",
	["Tus habilidades de ira te curan: menos descanso."] = "Suas habilidades de raiva curam você: menos descanso.",
	["Tus habilidades nuevas"] = "Suas habilidades novas",
	["Tus hechizos de daño pegan más."] = "Seus feitiços de dano batem mais.",
	["Tus hechizos de escarcha frenan: el monstruo casi nunca llega a pegarte."] = "Seus feitiços de gelo deixam lento: o monstro quase nunca consegue bater em você.",
	["Tus hechizos fallan menos."] = "Seus feitiços erram menos.",
