	["Tus marcos están listos"] = "Seus quadros estão prontos",
	["Tus metas en tu orden: un objeto, oro, una profesión, un lugar..."] = "Suas metas na sua ordem: um item, ouro, uma profissão, um lugar...",
	["Tus misiones abiertas, para terminarlas y entregarlas por el camino más corto."] = "Suas missões abertas, para terminar e entregar pelo caminho mais curto.",
	["Tus números"] = "Seus números",
	["Tus personajes"] = "Seus personagens",
	["Tus precios de la subasta son viejos: escanéala otra vez."] = "Seus preços do leilão estão velhos: escaneie de novo.",
	["Tus profesiones"] = "Suas profissões",
	["Tus próximos golpes también alcanzan a otro enemigo."] = "Seus próximos golpes também acertam outro inimigo.",
	["Tus puntos"] = "Seus pontos",
