	["Tú"] = "Você",
	["Tú recibes los golpes y proteges al grupo. Necesitas escudo."] = "Você recebe os golpes e protege o grupo. Precisa de escudo.",
	["Ubicación de %s"] = "Localização de %s",
	["Ultra"] = "Ultra",
	["Un arma en cada mano y mucha ira: el que más daño hace en grupo."] = "Uma arma em cada mão e muita raiva: o que mais causa dano em grupo.",
	["Un arma grande de dos manos y golpes que hacen sangrar. La forma más fácil de subir."] = "Uma arma grande de duas mãos e golpes que fazem sangrar. O jeito mais fácil de subir de nível.",
	["Un aturdimiento cuando lo necesites."] = "Um atordoamento quando você precisar.",
	["Un aullido de lobo, del propio juego, la primera vez que abres Alfa en cada sesión."] = "Um uivo de lobo, do próprio jogo, na primeira vez que você abre o Alfa em cada sessão.",
	["Un aviso con sus jefes y lo que llevas vencido, con un clic a sus consejos."] = "Um aviso com os chefes e quantos você já derrotou, a um clique das dicas.",
	["Un aviso corto con el lugar, su zona y el tiempo de camino."] = "Um aviso curto com o lugar, a zona e o tempo de caminho.",
	["Un aviso corto cuando se activa una habilidad que depende de lo que pasó, como Abrumar después de que el enemigo esquive."] = "Um aviso curto quando é ativada uma habilidade que depende do que aconteceu, como Sobrepujar depois que o inimigo se esquiva.",
	["Un aviso cuando vences a un jefe nuevo, con un clic a su botín."] = "Um aviso quando você derrota um chefe novo, a um clique do saque dele.",
	["Un aviso y una franja en tus bolsas con qué vender, qué conservar y a qué comerciante ir, con un clic para marcar la chatarra."] = "Um aviso e uma faixa nas suas bolsas com o que vender, o que guardar e a qual mercador ir, com um clique para marcar o lixo.",
	["Un barrido oscuro y suave sobre los íconos mientras su recarga corre."] = "Uma varredura escura e suave sobre os ícones enquanto a recarga corre.",
	["Un borde del color de la calidad: verde, azul, morado..."] = "Uma borda da cor da qualidade: verde, azul, roxo...",
	["Un borde dorado que late y una insignia «!» en lo que sirve para una misión; la insignia va llena si el objeto empieza una."] = "Uma borda dourada que pulsa e um selo «!» em tudo que serve para uma missão; o selo fica cheio se o item inicia uma.",
	["Un borde verde que late sobre el botón de tu barra con la habilidad sugerida, para encontrarlo rápido."] = "Uma borda verde pulsante sobre o botão da sua barra com a habilidade sugerida, para achá-lo rápido.",
	["Un buzón"] = "Uma caixa de correio",
	["Un clic bajito cuando Lya te dice algo."] = "Um clique baixinho quando a Lya diz algo.",
	["Un clic y queda solo lo esencial: tú, tu grupo, tus marcadores y el siguiente paso de la guía."] = "Um clique e fica só o essencial: você, seu grupo, seus marcadores e o próximo passo do guia.",
	["Un cuadro pequeño y movible con tu vida y las estadísticas que más pesan para tu clase. En combate el juego oculta algunos números: se queda el último que se pudo leer."] = "Um quadro pequeno e móvel com sua vida e os atributos que mais pesam para sua classe. Em combate, o jogo esconde alguns números: fica o último que deu para ler.",
	["Un enemigo"] = "Um inimigo",
	["Un error, una mejora o un comentario, directo al desarrollador"] = "Um erro, uma melhoria ou um comentário, direto para o desenvolvedor",
	["Un fondo del color de tu clase bajo tu nombre."] = "Um fundo da cor da sua classe embaixo do seu nome.",
	["Un golpe enorme con el escudo y muchísima amenaza."] = "Um golpe enorme com o escudo e muitíssima ameaça.",
	["Un golpe más para gastar ira."] = "Mais um golpe para gastar raiva.",
	["Un golpe nuevo y fuerte para tu barra."] = "Um golpe novo e forte para a sua barra.",
	["Un gran aumento de daño para monstruos difíciles; además te libra del miedo."] = "Um grande aumento de dano para monstros difíceis; além disso, livra você do medo.",
	["Un grano fino de cine sobre el mundo."] = "Um granulado fino de cinema sobre o mundo.",
	["Un grano fino, como de cine. Casi no cuesta: se mueve unas 14 veces por segundo y solo mientras se ve."] = "Um granulado fino, como de cinema. Quase não custa nada: muda umas 14 vezes por segundo e só enquanto aparece.",
	["Un hechizo de tus barras tiene un rango viejo"] = "Um feitiço das suas barras está num grau antigo",
	["Un marco dorado en lo que sirve para una misión (con «!» si empieza una)."] = "Uma moldura dourada no que serve para uma missão (com “!” se ele inicia uma).",
	["Un objeto que quieres: Alfa arma el camino para conseguirlo, con lo que haga falta antes."] = "Um item que você quer: o Alfa monta o caminho para consegui-lo, com o que for preciso antes.",
	["Un paisaje más bonito"] = "Uma paisagem mais bonita",
	["Un pescadito asado no me caería nada mal."] = "Um peixinho assado não cairia nada mal.",
	["Un pin pequeño con su número donde te llevan los próximos pasos."] = "Um pequeno marcador numerado onde os próximos passos vão levar você.",
	["Un poco de golpe crítico, de esquivar y de armadura."] = "Um pouco de acerto crítico, esquiva e armadura.",
	["Un poco de vida de vuelta después de críticos."] = "Um pouco de vida de volta depois de críticos.",
	["Un poco más de defensa."] = "Um pouco mais de defesa.",
	["Un poco más de ira al cargar."] = "Um pouco mais de raiva ao usar Investida.",
	["Un punto para abrir la siguiente fila y fallar un poco menos."] = "Um ponto para abrir a próxima fileira e errar um pouco menos.",
	["Un servicio cercano, un marcador de tu mapa, donde estás ahora o la entrada de una mazmorra."] = "Um serviço próximo, um marcador do seu mapa, onde você está agora ou a entrada de uma masmorra.",
	["Un signo de exclamación sobre quien te da misiones de tu nivel."] = "Um ponto de exclamação sobre quem dá missões do seu nível.",
	["Un signo de interrogación sobre quien recibe una misión ya lista."] = "Um ponto de interrogação sobre quem recebe uma missão já concluída.",
	["Un solo addon con todo lo que usas al jugar: guías paso a paso con flecha y ruta, mapa, bolsas, builds, curación con clic, recolección, mazmorras, pesca y comercio. Todo con el mismo estilo."] = "Um único addon com tudo o que você usa ao jogar: guias passo a passo com seta e rota, mapa, bolsas, builds, cura com clique, coleta, masmorras, pesca e comércio. Tudo no mesmo estilo.",
	["Un tanque que pega fuerte: mucha amenaza para grupos que hacen mucho daño, a cambio de menos defensa extra. Para tanques con algo de experiencia."] = "Um tanque que bate forte: muita ameaça para grupos que causam muito dano, em troca de menos defesa extra. Para tanques com alguma experiência.",
	["Un ícono con la habilidad que conviene ahora. Solo muestra: nunca aprieta nada por ti."] = "Um ícone com a habilidade que convém agora. Só mostra: nunca aperta nada por você.",
	["Un ícono de misión en la placa de nombre de los enemigos y personajes que todavía necesitas para una misión de tu registro. En mazmorras el juego oculta esos datos y no se marcan."] = "Um ícone de missão na placa de nome dos inimigos e personagens que você ainda precisa para uma missão do seu registro. Em masmorras o jogo esconde esses dados e eles não são marcados.",
	["Una acción recomendada en grande y tu camino en un par de clics."] = "Uma ação recomendada em destaque e seu caminho em poucos cliques.",
	["Una barra con los ataques que el jefe va a hacer y cuánto falta para cada uno. Así sabes cuándo moverte o defenderte."] = "Uma barra com os ataques que o chefe vai fazer e quanto falta para cada um. Assim você sabe quando se mover ou se defender.",
	["Una cadena de texto lleva un build completo: la copias, la pasas y la pegan."] = "Um texto leva uma build completa: você copia, passa adiante e eles colam.",
	["Una cantidad de oro; se cumple cuando la llevas encima."] = "Uma quantidade de ouro; fica cumprida quando você a carrega.",
	["Una categoría…"] = "Uma categoria…",
	["Una cuenta de prueba no puede compartir"] = "Uma conta de teste não pode compartilhar",
	["Una fila con vuelo, posada, reparar, banco, buzón y tu entrenador, a un clic."] = "Uma fileira com voo, estalagem, reparo, banco, correio e seu instrutor, a um clique.",
	["Una flecha en pantalla que apunta a tu siguiente objetivo, con la distancia. Apagada: tú decides por dónde ir."] = "Uma seta na tela que aponta para o seu próximo objetivo, com a distância. Desligada: você decide por onde ir.",
	["Una flecha verde en cada objeto de tus bolsas que es una mejora para tu especialización."] = "Uma seta verde em cada item das suas bolsas que é uma melhoria para a sua especialização.",
	["Una flecha verde en el equipo que es mejor que lo que llevas puesto, según tu clase y nivel."] = "Uma seta verde no equipamento melhor do que o que você está usando, de acordo com sua classe e nível.",
	["Una franja verde clara muestra las curas que ya vienen en camino."] = "Uma faixa verde-clara mostra as curas que já estão a caminho.",
	["Una guía para tu nivel y tu zona, o tu propia ruta de misiones."] = "Um guia para o seu nível e sua zona, ou sua própria rota de missões.",
	["Una loba negra que te da consejos y ánimo en el camino, sin estorbar. En memoria de una gran perrita."] = "Uma loba negra que dá dicas e ânimo pelo caminho, sem atrapalhar. Em memória de uma cachorrinha incrível.",
	["Una línea corta debajo del ícono, como «Golpe mortal: recarga lista». Cada una sale hasta 4 veces y luego se calla; su × la calla antes."] = "Uma linha curta embaixo do ícone, como «Golpe Mortal: recarga pronta». Cada uma aparece até 4 vezes e depois se cala; o × dela a cala antes.",
	["Una línea debajo del aviso con lo que pasó."] = "Uma linha embaixo do aviso com o que aconteceu.",
	["Una línea roja arriba avisa cuando un enemigo va por ese compañero."] = "Uma linha vermelha em cima avisa quando um inimigo vai atrás desse companheiro.",
	["Una mano"] = "Uma Mão",
	["Una meta que marcas tú (el botón de hecha del rastreador o de esta lista)."] = "Uma meta que você marca (o botão de feita do rastreador ou desta lista).",
	["Una misión"] = "Uma missão",
	["Una moneda sobre lo gris y lo que marcaste como chatarra."] = "Uma moeda sobre o cinza e o que você marcou como lixo.",
	["Una nota con el instructor más cercano cuando tienes habilidades nuevas."] = "Uma nota com o instrutor mais próximo quando você tem habilidades novas.",
	["Una ruta es tu árbol de tramos: misiones de XP, de oro, de clase, materiales u objetos. Empieza con una plantilla."] = "Uma rota é sua árvore de trechos: missões de XP, de ouro, de classe, materiais ou itens. Comece com um modelo.",
	["Una ruta necesita al menos 3 lugares que tu habilidad alcance. Elige otro tipo o recurso abajo, o recolecta aquí: Alfa anota cada nodo que encuentras."] = "Uma rota precisa de pelo menos 3 lugares que sua habilidade alcance. Escolha outro tipo ou recurso abaixo, ou colete aqui: o Alfa anota cada ponto que você encontra.",
	["Una ruta por los mejores lugares para tu habilidad, con unas misiones de XP en medio."] = "Uma rota pelos melhores lugares para sua habilidade, com algumas missões de XP no meio.",
	["Una sesión termina tras 20 minutos sin lanzar o cuando empiezas otra; entonces aparece aquí con lo que sacaste y dónde."] = "Uma sessão termina após 20 minutos sem lançar ou quando você começa outra; então aparece aqui com o que você pescou e onde.",
	["Una sesión tranquila: nada nuevo que contar."] = "Uma sessão tranquila: nada de novo para contar.",
	["Una tecla para todo: equipo, cebo, lanzar y recoger. Con diario, guía, cocina, metas y estadísticas."] = "Uma tecla para tudo: equipamento, isca, lançar e recolher. Com diário, guia, culinária, metas e estatísticas.",
	["Une los %d lugares que tu habilidad alcanza en una vuelta corta, la dibuja en el mapa y la flecha te lleva de parada en parada."] = "Une os %d lugares que sua habilidade alcança numa volta curta, desenha no mapa e a seta leva você de parada em parada.",
	["Unir las capas de sombra"] = "Unir as camadas de sombra",
	["Unirte al grupo de tus amigos"] = "Entrar no grupo dos seus amigos",
	["Uno menos"] = "Um a menos",
	["Uno más"] = "Um a mais",
	["Usa %s"] = "Use %s",
	["Usa %s: tu tecla lo pone."] = "Use %s: sua tecla coloca.",
	["Usa Bloquear con escudo cuando un jefe pegue fuerte."] = "Use Shield Block quando um chefe bater forte.",
	["Usa Deseo de muerte al empezar contra un jefe."] = "Use Desejo de Morte no começo da luta contra um chefe.",
	["Usa Deseo de muerte con monstruos difíciles, no con los fáciles."] = "Use Desejo de Morte com monstros difíceis, não com os fáceis.",
	["Usa Golpe mortal sobre todo contra sanadores."] = "Use Golpe Mortal principalmente contra curadores.",
	["Usa Golpes de barrido cuando haya dos o más enemigos juntos."] = "Use Sweeping Strikes quando houver dois ou mais inimigos juntos.",
	["Usa Ira rabiosa para romper miedos."] = "Use Berserker Rage para quebrar medos.",
